<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Profile\Infrastructure\Driven;

use Override;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\OAuth\Profile\Domain\Gateway\PasskeysGateway;
use Civi\Lughauth\Features\OAuth\WebAuthn\Domain\Gateway\WebAuthnCredentialGateway;

final class PasskeysAdapter implements PasskeysGateway
{
    public function __construct(
        private readonly WebAuthnCredentialGateway $credentials,
        private readonly TenantReadGateway $tenants,
    ) {
    }

    #[Override]
    public function listByUser(string $userUid, string $tenant): array
    {
        $tenantEntity = $this->tenants->findOneByName($tenant) ?? $this->tenants->findOneByDomain($tenant);
        if ($tenantEntity === null) {
            return [];
        }
        return $this->credentials->findByUser($userUid, (string) $tenantEntity->uid());
    }

    #[Override]
    public function disableByUid(string $credentialUid, string $tenant): void
    {
        $tenantEntity = $this->tenants->findOneByName($tenant) ?? $this->tenants->findOneByDomain($tenant);
        if ($tenantEntity === null) {
            return;
        }
        $this->credentials->disableByUid($credentialUid, (string) $tenantEntity->uid());
    }

    #[Override]
    public function renameByUid(string $credentialUid, string $tenant, string $name): void
    {
        $tenantEntity = $this->tenants->findOneByName($tenant) ?? $this->tenants->findOneByDomain($tenant);
        if ($tenantEntity === null) {
            return;
        }
        $this->credentials->renameByUid($credentialUid, (string) $tenantEntity->uid(), $name);
    }
}
